// ./schema.d.ts is generated by `bun run gen:api` from crates/zeabur-api/openapi.yaml.
import createClient from "openapi-fetch"

import type { components, paths } from "@/api/schema"
import { BACKGROUND_HEADER, backgroundNow, goToSignIn, REQUEST_HEADERS } from "@/auth/session"

export type Schemas = components["schemas"]
export type Problem = Schemas["Problem"]

export const api = createClient<paths>({ credentials: "same-origin", headers: REQUEST_HEADERS })

api.use({
  onRequest: ({ request }) => {
    if (backgroundNow(request.method)) request.headers.set(BACKGROUND_HEADER, "1")
    return request
  },
})

/** Carries the server's problem (RFC 9457). */
export class ApiError extends Error {
  readonly status: number
  readonly problem: Problem
  /** Seconds; set on a 429 or 503 only. */
  readonly retryAfter: number | undefined

  constructor(status: number, problem: Problem, retryAfter?: number) {
    super(problem.detail)
    this.name = "ApiError"
    this.status = status
    this.problem = problem
    this.retryAfter = retryAfter
  }
}

/** No answer from the cluster or from Zeabur itself, as opposed to a refusal or a bad request. */
export function isUnreachable(error: unknown): boolean {
  if (!(error instanceof ApiError)) return error instanceof Error
  return (
    error.problem.kind === "unavailable" ||
    error.status === 0 ||
    error.status === 502 ||
    error.status === 504
  )
}

/** Seconds or an HTTP-date (RFC 9110, section 10.2.3); a past date is 0. */
export function retryAfterSeconds(value: string | null, now = Date.now()): number | undefined {
  const text = value?.trim()
  if (!text) return undefined
  if (/^\d+$/.test(text)) return Number(text)
  // Every HTTP-date format starts with the day's name (section 5.6.7); `Date.parse` alone would
  // read `-5` as a year.
  if (!/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun)/.test(text)) return undefined
  const date = Date.parse(text)
  if (Number.isNaN(date)) return undefined
  return Math.max(0, Math.ceil((date - now) / 1000))
}

function isProblem(value: unknown): value is Problem {
  return (
    typeof value === "object" &&
    value !== null &&
    "title" in value &&
    "detail" in value &&
    "fix" in value
  )
}

/** For answers that carry none (a proxy error, a dropped connection). */
export function localProblem(status: number, detail: string): Problem {
  const kind = status === 0 ? "unavailable" : status >= 500 ? "internal" : "bad-request"
  return {
    type: "about:blank",
    title: status === 0 ? "Zeabur didn't respond" : `HTTP ${status}`,
    status,
    detail,
    fix: "Check that Zeabur is still running, then reload the page.",
    fixKey: { key: "page.reload" },
    kind,
    summary:
      status === 0
        ? { key: "page.noAnswer" }
        : { key: "page.status", params: { status: String(status) } },
  }
}

export function unwrap<T>(result: { data?: T; error?: unknown; response: Response }): T {
  if (result.data !== undefined && result.response.ok) return result.data
  const status = result.response.status
  const reason = result.response.statusText
  const problem = isProblem(result.error)
    ? result.error
    : localProblem(status, `The server answered ${reason ? `${status} ${reason}` : status}.`)
  if (problem.kind === "signed-out") goToSignIn()
  // RFC 6585, section 4; RFC 9110, section 15.6.4. Else kube-apiserver's Status retry hint.
  const retryAfter =
    status === 429 || status === 503
      ? (retryAfterSeconds(result.response.headers.get("retry-after")) ??
        problem.kubernetes?.retryAfterSeconds ??
        undefined)
      : undefined
  throw new ApiError(status, problem, retryAfter)
}

export function toProblem(error: unknown): Problem {
  if (error instanceof ApiError) return error.problem
  if (error instanceof Error) return localProblem(0, error.message)
  return localProblem(0, String(error))
}

export function isStatus(error: unknown, status: number): boolean {
  return error instanceof ApiError && error.status === status
}
